1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
57	// Base premium for a single item of each type.
58	const UNIT_BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const LOYALTY_YEARS_THRESHOLD = 2;
68	const LOYALTY_DISCOUNT_RATE = 2 / 10;
69	const FOLLOW_UP_DISCOUNT_RATE = 15 / 100;
70	const CURSE_SURCHARGE_RATE = 1 / 2;
71	const HIGH_ENCHANTMENT_THRESHOLD = 5;
72	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
73	const BLOCK_SIZE = 3;
74	const BLOCK_BASE_PREMIUM = 60;
75	const DEDUCTIBLE = 100;
76	const CAP_MULTIPLIER = 2;
77	
78	// Insurance value of a single item of each type.
79	const INSURANCE_VALUES: Record<string, number> = {
80	  sword: 1000,
81	  amulet: 600,
82	  staff: 800,
83	  potion: 400,
84	  rune: 250,
85	  moonstone: 250,
86	};
87	
88	const unitBasePremium = (type: string): number => UNIT_BASE_PREMIUMS[type];
89	
90	const countByType = (items: Item[]): Map<string, number> =>
91	  items.reduce(
92	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
93	    new Map<string, number>(),
94	  );
95	
96	// A building block of 3 alike components is offered at a special base premium.
97	const basePremiumForItemGroup = (type: string, count: number): number =>
98	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
99	
100	const policyBasePremium = (items: Item[]): number =>
101	  [...countByType(items)].reduce(
102	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
103	    0,
104	  );
105	
106	const isHighlyEnchanted = (item: Item): boolean =>
107	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
108	
109	const surchargeRate = (item: Item): number =>
110	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
111	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
112	
113	// Item-specific modifiers apply to the affected item's own base premium, i.e.
114	// the unit price of its type — a block discount never shrinks a surcharge.
115	const itemSurcharge = (item: Item): number =>
116	  unitBasePremium(item.type) * surchargeRate(item);
117	
118	const itemSurcharges = (items: Item[]): number =>
119	  items.reduce((total, item) => total + itemSurcharge(item), 0);
120	
121	const isLongStanding = (customer: Customer): boolean =>
122	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
123	
124	// Policy-wide modifiers apply to the policy base premium only — never to the
125	// item surcharges. Net signed delta: a discount can outweigh the surcharge.
126	// Every quote is a first insurance for its items, regardless of customer
127	// history, so that surcharge always applies.
128	const policyAdjustmentRate = (
129	  customer: Customer,
130	  isFollowUpContract: boolean,
131	): number =>
132	  FIRST_INSURANCE_SURCHARGE_RATE -
133	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
134	  (isFollowUpContract ? FOLLOW_UP_DISCOUNT_RATE : 0);
135	
136	// Premiums round up, in the MHPCO's favour. The adjustment is added as a
137	// separate term rather than folded into a `base * 1.1` factor, which is not
138	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
139	const quotePremium = (
140	  items: Item[],
141	  customer: Customer,
142	  isFollowUpContract: boolean,
143	): number => {
144	  const base = policyBasePremium(items);
145	  return Math.ceil(
146	    base +
147	      itemSurcharges(items) +
148	      base * policyAdjustmentRate(customer, isFollowUpContract) +
149	      PROCESSING_FEE,
150	  );
151	};
152	
153	// The total payout per policy is capped at twice the insurance sum.
154	const insuranceSum = (items: Item[]): number =>
155	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
156	
157	// A policy created by a quote step, tracked so later claims can pay out
158	// against it. `remainingCap` shrinks as successive claims are settled.
159	interface Policy {
160	  items: Item[];
161	  remainingCap: number;
162	}
163	
164	const openPolicy = (items: Item[]): Policy => ({
165	  items,
166	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
167	});
168	
169	// State accumulated by the steps run so far. Later steps price and pay out
170	// against what earlier steps established, so each step reads the state it was
171	// run with and returns the state the next step should see.
172	interface ScenarioState {
173	  customer: Customer;
174	  contractsSoFar: number;
175	  // Keyed by the zero-based index of the quote step that created the policy.
176	  policies: Map<number, Policy>;
177	}
178	
179	// A step's outcome: what to report, and how the scenario stands afterwards.
180	interface StepOutcome {
181	  result: Result;
182	  state: ScenarioState;
183	}
184	
185	const quote = (
186	  step: QuoteStep,
187	  state: ScenarioState,
188	  stepIndex: number,
189	): StepOutcome => ({
190	  result: {
191	    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
192	  },
193	  state: {
194	    ...state,
195	    contractsSoFar: state.contractsSoFar + 1,
196	    policies: new Map(state.policies).set(stepIndex, openPolicy(step.items)),
197	  },
198	});
199	
200	// A deductible applies per damage event, i.e. once per damaged item.
201	const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;
202	
203	const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
204	  const policy = state.policies.get(step.policy)!;
205	  const payout = step.incident.damages.reduce(
206	    (total, damage) => total + damagePayout(damage),
207	    0,
208	  );
209	  const remainingCap = policy.remainingCap - payout;
210	  return {
211	    result: { payout, remainingCap },
212	    state: {
213	      ...state,
214	      policies: new Map(state.policies).set(step.policy, {
215	        ...policy,
216	        remainingCap,
217	      }),
218	    },
219	  };
220	};
221	
222	const runStep = (
223	  step: Step,
224	  state: ScenarioState,
225	  stepIndex: number,
226	): StepOutcome => {
227	  switch (step.op) {
228	    case "quote":
229	      return quote(step, state, stepIndex);
230	    case "claim":
231	      return claim(step, state);
232	  }
233	};
234	
235	export const runScenario = (scenario: Scenario): ScenarioResult => {
236	  const initialState: ScenarioState = {
237	    customer: scenario.customer,
238	    contractsSoFar: 0,
239	    policies: new Map(),
240	  };
241	  const { results } = scenario.steps.reduce<{
242	    results: Result[];
243	    state: ScenarioState;
244	  }>(
245	    ({ results, state }, step, stepIndex) => {
246	      const outcome = runStep(step, state, stepIndex);
247	      return { results: [...results, outcome.result], state: outcome.state };
248	    },
249	    { results: [], state: initialState },
250	  );
251	  return { results };
252	};
